const menu=document.querySelector('#menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');document.querySelector('.dropdown').classList.remove('open');document.querySelector('.dropdown-toggle').setAttribute('aria-expanded','false')}});document.querySelector('.dropdown-toggle').addEventListener('click',e=>{const open=e.currentTarget.parentElement.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page')});const sticky=document.querySelector('.mobile-call');new IntersectionObserver(entries=>{sticky.classList.toggle('visible',!entries[0].isIntersecting)},{threshold:0}).observe(document.querySelector('.hero,.page-hero'));const steps=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('active')}),{threshold:.6});document.querySelectorAll('.steps article,.process-step').forEach(e=>steps.observe(e));const viewer=document.querySelector('#viewer');document.querySelector('.gallery-open')?.addEventListener('click',()=>viewer.showModal());document.querySelector('#close-viewer').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});document.querySelector('#check-location')?.addEventListener('click',()=>{const value=document.querySelector('#location').value.trim();document.querySelector('#location-result').textContent=value?'When you call, tell Dave your pickup location is '+value+'. Call 414-629-3990 to confirm coverage and availability. This does not request or confirm dispatch.':'Please enter your pickup city, ZIP code, or a nearby landmark.'});



